<template>
	<div class="flex min-h-dvh flex-col bg-ui-surface-gray-50 pb-safe">
		<!-- ============ HEADER ============ -->
		<div
			ref="headerRef"
			class="sticky top-0 z-30 border-b border-ui-line-gray-200 bg-ui-surface px-5 py-4"
			style="padding-top: calc(1rem + env(safe-area-inset-top))"
		>
			<div class="flex items-center gap-2">
				<RouterLink
					:to="backTarget"
					replace
					class="-ml-1 flex h-10 w-10 shrink-0 items-center justify-center rounded-md text-ui-action transition-colors hover:bg-ui-surface-blue-50 active:bg-ui-surface-blue-100"
					:title="`Kembali ke ${backLabel}`"
					:aria-label="`Kembali ke ${backLabel}`"
				>
					<svg
						xmlns="http://www.w3.org/2000/svg"
						viewBox="0 0 24 24"
						class="h-7 w-7"
						fill="none"
						stroke="currentColor"
						stroke-width="2"
						stroke-linecap="round"
						stroke-linejoin="round"
					>
						<path d="m12 19-7-7 7-7" />
						<path d="M19 12H5" />
					</svg>
				</RouterLink>

				<div class="flex min-w-0 flex-1 flex-col justify-center gap-1">
					<nav class="hidden min-w-0 items-center gap-1.5 text-sm md:flex">
						<RouterLink
							:to="backTarget"
							replace
							class="text-ui-ink-gray-500 hover:text-ui-ink-gray-700 hover:underline"
						>
							{{ backLabel }}
						</RouterLink>
						<span class="text-ui-ink-gray-300">/</span>
						<span class="truncate font-medium text-ui-ink-gray-900">{{ displayTitle }}</span>
					</nav>
					<span class="min-w-0 truncate font-medium text-ui-ink-gray-900 md:hidden">{{
						displayTitle
					}}</span>
					<span
						v-if="doc.data?.status"
						class="w-fit shrink-0 rounded-full px-2.5 py-0.5 text-base font-medium leading-snug"
						:class="statusPill(doc.data.status)"
					>
						{{ doc.data.status }}
					</span>
				</div>
			</div>
		</div>

		<!-- ============ KONTEN ============ -->
		<div class="flex flex-1 flex-col">
			<p v-if="doc.loading" class="px-6 py-4 text-sm text-ui-ink-gray-500">Loading...</p>

			<pre
				v-else-if="doc.error"
				class="px-6 py-4 text-sm text-ui-ink-red-600 whitespace-pre-wrap"
				>{{ doc.error.message || doc.error }}</pre
			>

			<div v-else-if="doc.data" class="text-base">
				<!-- Tab strip -->
				<div
					ref="tabStripRef"
					:style="{ top: tabTop + 'px' }"
					class="scrollbar-hide sticky z-20 flex gap-1 overflow-x-auto border-b border-ui-line-gray-200 bg-ui-surface px-4 md:px-6"
				>
					<button
						v-for="tab in visibleTabs"
						:key="tab.key"
						type="button"
						class="-mb-px flex shrink-0 items-center gap-1.5 whitespace-nowrap border-b-2 px-3 py-3 text-sm font-medium transition"
						:class="
							activeTab === tab.key
								? 'border-ui-line-gray-800 text-ui-ink-gray-900'
								: 'border-transparent text-ui-ink-gray-500 hover:text-ui-ink-gray-700'
						"
						@click="activeTab = tab.key"
					>
						{{ tab.label }}
					</button>
				</div>

				<!-- Isi tab aktif -->
				<div class="app-container-narrow space-y-4 px-4 py-5 md:px-6">
					<template v-if="activeTabObj">
						<template v-for="(item, ii) in activeTabObj.items" :key="ii">
							<!-- ===== Section field biasa ===== -->
							<section
								v-if="item.type === 'section'"
								class="rounded-2xl border border-ui-line-gray-100 bg-ui-surface p-4 shadow-sm md:p-5"
							>
								<h3
									v-if="item.label"
									class="mb-3 text-lg font-semibold text-primary"
								>
									{{ item.label }}
								</h3>
								<div class="flex flex-col gap-x-6 gap-y-4 md:flex-row">
									<div
										v-for="(col, ci) in item.columns"
										:key="ci"
										class="flex-1 space-y-4"
									>
										<div v-for="field in col" :key="field.fieldname">
											<label
												class="mb-1 block text-base font-medium text-ui-ink-gray-500"
												>{{ field.label }}</label
											>
											<p
												v-if="isTextarea(field.fieldtype)"
												class="min-h-[1.25rem] whitespace-pre-line break-words text-base text-ui-ink-gray-800"
											>
												{{
													valueDisplay(field, doc.data[field.fieldname])
												}}
											</p>
											<p
												v-else
												class="min-h-[1.25rem] break-words text-base"
												:class="
													field.fieldtype === 'Currency'
														? 'font-medium text-ui-ink-gray-900'
														: 'text-ui-ink-gray-800'
												"
											>
												{{
													valueDisplay(field, doc.data[field.fieldname])
												}}
											</p>
										</div>
									</div>
								</div>
							</section>

							<!-- ===== Tabel → kelompok card accordion ===== -->
							<section v-else-if="item.type === 'table'">
								<div class="mb-2 flex items-center justify-between gap-2 px-0.5">
									<h3 class="text-lg font-semibold text-primary">
										{{ item.label }}
									</h3>
									<span
										class="shrink-0 rounded-full bg-ui-surface-gray-100 px-2.5 py-0.5 text-xs font-medium text-ui-ink-gray-500"
									>
										{{ item.rows.length }} data
									</span>
								</div>

								<div class="space-y-2.5">
									<div
										v-for="(row, ri) in item.rows"
										:key="row.name || ri"
										class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm"
									>
										<!-- Header card (klik buka/tutup) -->
										<button
											type="button"
											class="flex w-full items-center justify-between gap-3 px-4 py-3 text-left transition hover:bg-ui-surface-gray-50"
											@click="toggleRow(item.fieldname, row.name || ri)"
										>
											<span class="flex min-w-0 items-center gap-3">
												<span
													class="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-primary/10 text-xs font-semibold text-primary"
												>
													{{ ri + 1 }}
												</span>
												<span class="min-w-0">
													<span
														class="block truncate text-base font-semibold text-ui-ink-gray-900"
													>
														{{ cardTitle(item, row, ri) }}
													</span>
													<span
														v-if="cardSubtitle(item, row)"
														class="block truncate text-sm text-ui-ink-gray-400"
													>
														{{ cardSubtitle(item, row) }}
													</span>
												</span>
											</span>
											<svg
												xmlns="http://www.w3.org/2000/svg"
												viewBox="0 0 24 24"
												class="h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform"
												:class="{
													'rotate-180': isRowOpen(
														item.fieldname,
														row.name || ri
													),
												}"
												fill="none"
												stroke="currentColor"
												stroke-width="2"
												stroke-linecap="round"
												stroke-linejoin="round"
											>
												<path d="m6 9 6 6 6-6" />
											</svg>
										</button>

										<!-- Isi card -->
										<div
											v-if="isRowOpen(item.fieldname, row.name || ri)"
											class="border-t border-ui-line-gray-100 px-4 py-3"
										>
											<dl
												class="grid grid-cols-1 gap-x-6 gap-y-3 sm:grid-cols-2"
											>
												<div
													v-for="cf in cardDetails(item, row)"
													:key="cf.fieldname"
												>
													<dt class="text-sm font-medium text-ui-ink-gray-500">
														{{ cf.label }}
													</dt>
													<dd
														class="mt-0.5 break-words text-base text-ui-ink-gray-800"
													>
														<img
															v-if="
																isImageField(cf.fieldtype) &&
																cf.value
															"
															:src="cf.value"
															:alt="cf.label"
															class="mt-1 max-h-48 rounded-lg border border-ui-line-gray-200 object-contain"
														/>
														<span v-else class="whitespace-pre-line">{{
															cf.display
														}}</span>
													</dd>
												</div>
											</dl>
											<p
												v-if="!cardDetails(item, row).length"
												class="text-sm text-ui-ink-gray-400"
											>
												Tidak ada detail.
											</p>
										</div>
									</div>
								</div>
							</section>
						</template>
					</template>

					<p v-else class="py-10 text-center text-sm text-ui-ink-gray-400">
						Tidak ada data yang dapat ditampilkan.
					</p>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { createResource } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { useBackNavigation } from '../composables/useBackNavigation'

const DOCTYPE = 'Master Data Nasabah'
const route = useRoute()
const { backTarget, backLabel } = useBackNavigation(
	{ name: 'MasterDataNasabah' },
	'Master Data Nasabah',
)
const name = computed(() => route.params.name)

const displayTitle = computed(() => doc.data?.nama_nasabah || name.value)

// Warna pill status (selaras Document States: Aktif=Blue, Lunas=Green, AYDA=Red).
const STATUS_PILL = {
	Aktif: 'bg-ui-surface-blue-100 text-ui-ink-blue-700',
	Lunas: 'bg-ui-surface-green-100 text-ui-ink-green-700',
	AYDA: 'bg-ui-surface-red-100 text-ui-ink-red-700',
}
function statusPill(s) {
	return STATUS_PILL[s] || 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
}

// ---- Fetch dokumen (termasuk semua child table) ----------------------------
const doc = createResource({
	url: 'frappe.client.get',
	makeParams() {
		return { doctype: DOCTYPE, name: name.value }
	},
	auto: false,
})

// ---- Meta doctype induk + child --------------------------------------------
const metaFields = ref([])
// childMeta[doctype] = array field def (input field, sudah tersaring).
const childMeta = reactive({})

const SKIP_TYPES = [
	'Section Break',
	'Column Break',
	'Tab Break',
	'HTML',
	'Button',
	'Heading',
	'Fold',
	'Barcode',
]
const STRUCT_TYPES = ['Section Break', 'Column Break', 'Tab Break']

function isTextarea(ft) {
	return ['Small Text', 'Text', 'Long Text', 'Code', 'Text Editor'].includes(ft)
}
function isImageField(ft) {
	return ['Image', 'Attach Image'].includes(ft)
}

// Field child yang bisa ditampilkan (buang struktural / hidden / non-data).
function displayableChildFields(dt) {
	const fields = childMeta[dt] || []
	return fields.filter(
		(f) =>
			!STRUCT_TYPES.includes(f.fieldtype) &&
			!['HTML', 'Button', 'Heading', 'Fold', 'Barcode'].includes(f.fieldtype) &&
			!f.hidden
	)
}

// ---- Format nilai ----------------------------------------------------------
function isEmpty(v) {
	return v == null || (typeof v === 'string' && v.trim() === '')
}
function formatDate(v) {
	if (!v) return ''
	const m = String(v).match(/^(\d{4})-(\d{2})-(\d{2})/)
	return m ? `${m[3]}-${m[2]}-${m[1]}` : String(v)
}
function formatNumber(v) {
	const n = Number(v)
	return Number.isNaN(n) ? String(v) : new Intl.NumberFormat('id-ID').format(n)
}
function formatCurrency(v) {
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID', {
		minimumFractionDigits: 0,
		maximumFractionDigits: 2,
	}).format(n)}`
}
// Tampilan nilai berdasar fieldtype (untuk field kosong → "—").
function valueDisplay(field, v) {
	if (field.fieldtype === 'Check') return v ? 'Ya' : 'Tidak'
	if (isEmpty(v)) return '—'
	switch (field.fieldtype) {
		case 'Currency':
			return formatCurrency(v)
		case 'Date':
			return formatDate(v)
		case 'Datetime':
			return formatDate(v)
		case 'Float':
		case 'Int':
		case 'Percent':
			return formatNumber(v)
		default:
			return String(v)
	}
}
// Apakah field induk dianggap "ada isinya" (untuk hide-empty).
function hasValue(field, v) {
	if (field.fieldtype === 'Check') return !!v
	return !isEmpty(v)
}

// ---- Susun tab → item (section / table) dari meta induk ---------------------
const tabsStructure = computed(() => {
	const tabs = []
	let curTab = null
	let curSection = null
	let curCol = null
	let lastSectionLabel = ''

	const ensureTab = () => {
		if (!curTab) {
			curTab = { key: '__detail__', label: 'Detail', items: [] }
			tabs.push(curTab)
		}
	}
	const ensureSection = () => {
		if (!curSection) {
			curCol = []
			curSection = { type: 'section', label: '', columns: [curCol] }
			curTab.items.push(curSection)
		}
	}

	for (const f of metaFields.value) {
		const ft = f.fieldtype
		if (ft === 'Tab Break') {
			curTab = { key: f.fieldname, label: f.label || f.fieldname, items: [] }
			tabs.push(curTab)
			curSection = null
			curCol = null
			lastSectionLabel = ''
			continue
		}
		ensureTab()
		if (ft === 'Section Break') {
			curCol = []
			curSection = { type: 'section', label: f.label || '', columns: [curCol] }
			curTab.items.push(curSection)
			lastSectionLabel = f.label || ''
			continue
		}
		if (ft === 'Column Break') {
			if (!curSection) ensureSection()
			else {
				curCol = []
				curSection.columns.push(curCol)
			}
			continue
		}
		if (ft === 'Table') {
			curTab.items.push({
				type: 'table',
				fieldname: f.fieldname,
				label: f.label || lastSectionLabel || 'Data',
				options: f.options,
			})
			curSection = null
			curCol = null
			continue
		}
		if (SKIP_TYPES.includes(ft) || f.hidden) continue
		ensureSection()
		curCol.push(f)
	}
	return tabs
})

// Tab + item yang BENAR-BENAR punya data (sembunyikan field/section/table kosong).
const renderedTabs = computed(() => {
	const data = doc.data || {}
	const out = []
	for (const tab of tabsStructure.value) {
		const items = []
		for (const item of tab.items) {
			if (item.type === 'section') {
				const columns = item.columns
					.map((col) => col.filter((f) => hasValue(f, data[f.fieldname])))
					.filter((col) => col.length)
				if (columns.length) items.push({ ...item, columns })
			} else if (item.type === 'table') {
				const rows = Array.isArray(data[item.fieldname]) ? data[item.fieldname] : []
				if (rows.length) items.push({ ...item, rows })
			}
		}
		if (items.length) out.push({ key: tab.key, label: tab.label, items })
	}
	return out
})

const visibleTabs = computed(() => renderedTabs.value.map((t) => ({ key: t.key, label: t.label })))
const activeTab = ref('')
const activeTabObj = computed(() => renderedTabs.value.find((t) => t.key === activeTab.value))

// Pilih tab pertama yang berisi begitu data siap / berubah.
watch(
	renderedTabs,
	(tabs) => {
		if (!tabs.length) {
			activeTab.value = ''
			return
		}
		if (!tabs.some((t) => t.key === activeTab.value)) activeTab.value = tabs[0].key
		nextTick(measureSticky)
	},
	{ immediate: true }
)

// ---- Accordion card --------------------------------------------------------
const openRows = reactive(new Set())
function rowKey(fieldname, id) {
	return `${fieldname}::${id}`
}
function toggleRow(fieldname, id) {
	const k = rowKey(fieldname, id)
	if (openRows.has(k)) openRows.delete(k)
	else openRows.add(k)
}
function isRowOpen(fieldname, id) {
	return openRows.has(rowKey(fieldname, id))
}

// Field child untuk header & isi card.
function childListFields(item) {
	return displayableChildFields(item.options).filter((f) => f.in_list_view)
}
function cardTitle(item, row, ri) {
	const lf = childListFields(item)
	for (const f of lf) {
		if (
			isTextarea(f.fieldtype) ||
			['Data', 'Select', 'Link', 'Dynamic Link'].includes(f.fieldtype)
		) {
			if (!isEmpty(row[f.fieldname])) return valueDisplay(f, row[f.fieldname])
		}
	}
	// fallback: field non-tanggal pertama yang terisi
	for (const f of lf) {
		if (f.fieldtype !== 'Date' && !isEmpty(row[f.fieldname]))
			return valueDisplay(f, row[f.fieldname])
	}
	return `Item ${ri + 1}`
}
function cardSubtitle(item, row) {
	const lf = childListFields(item)
	const dateF = lf.find(
		(f) => ['Date', 'Datetime'].includes(f.fieldtype) && !isEmpty(row[f.fieldname])
	)
	if (dateF) return `${dateF.label}: ${valueDisplay(dateF, row[dateF.fieldname])}`
	return ''
}
function cardDetails(item, row) {
	return displayableChildFields(item.options)
		.filter((f) =>
			isImageField(f.fieldtype) ? !isEmpty(row[f.fieldname]) : hasValue(f, row[f.fieldname])
		)
		.map((f) => ({
			fieldname: f.fieldname,
			label: f.label || f.fieldname,
			fieldtype: f.fieldtype,
			value: row[f.fieldname],
			display: valueDisplay(f, row[f.fieldname]),
		}))
}

// ---- Muat meta (induk + child) ---------------------------------------------
async function fetchDoctypeMeta(dt) {
	const res = await fetch(
		`/api/method/frappe.desk.form.load.getdoctype?doctype=${encodeURIComponent(dt)}`,
		{ method: 'GET', credentials: 'include', headers: { Accept: 'application/json' } }
	)
	if (!res.ok) throw new Error(`HTTP ${res.status}`)
	const json = await res.json()
	const docs = json.docs || json.message?.docs || []
	const meta = docs.find((x) => x.name === dt) || docs[0]
	return (meta && meta.fields) || []
}

async function loadMeta() {
	try {
		metaFields.value = await fetchDoctypeMeta(DOCTYPE)
		// Muat meta tiap child doctype dari field Table.
		const tableDts = [
			...new Set(
				metaFields.value
					.filter((f) => f.fieldtype === 'Table' && f.options)
					.map((f) => f.options)
			),
		]
		await Promise.all(
			tableDts.map(async (dt) => {
				try {
					childMeta[dt] = await fetchDoctypeMeta(dt)
				} catch (e) {
					childMeta[dt] = []
				}
			})
		)
	} catch (e) {
		/* meta gagal → tab tidak terbentuk, dokumen tetap tampil kosong */
	}
}

// ---- Offset sticky (header + tab strip) ------------------------------------
const headerRef = ref(null)
const tabStripRef = ref(null)
const tabTop = ref(0)
function measureSticky() {
	const h = headerRef.value?.offsetHeight || 0
	tabTop.value = Math.max(0, h - 1)
}
let _stickyRO = null
onMounted(async () => {
	await refreshCsrfToken()
	doc.fetch()
	await loadMeta()
	nextTick(measureSticky)
	if (typeof ResizeObserver !== 'undefined') {
		_stickyRO = new ResizeObserver(() => measureSticky())
		if (headerRef.value) _stickyRO.observe(headerRef.value)
	}
	window.addEventListener('resize', measureSticky)
})
onBeforeUnmount(() => {
	_stickyRO?.disconnect()
	window.removeEventListener('resize', measureSticky)
})
</script>
